292:   _computeNextZone(z) {
293:     const nextRadius = Math.max(24, z.radius * 0.72);
294:     const maxOffset = Math.max(0, z.radius - nextRadius) * 0.72;
295:     const a = Math.random() * Math.PI * 2;
296:     const d = Math.random() * maxOffset;
297:     z.nextX = clamp(z.x + Math.cos(a) * d, -HALF + 80, HALF - 80);
298:     z.nextZ = clamp(z.z + Math.sin(a) * d, -HALF + 80, HALF - 80);
299:     z.nextRadius = nextRadius;
300:   }
