316:   _spawnLoot() {
317:     const spots = [...this.world.lootSpawns];
318:     for (let i = spots.length - 1; i > 0; i--) {
319:       const j = Math.floor(Math.random() * (i + 1));
320:       [spots[i], spots[j]] = [spots[j], spots[i]];
321:     }
322:     const weaponIds = ['ak47', 'ump', 'ak47', 'awm', 'ump', 'ak47', 'awm', 'ump'];
323:     let wi = 0;
324:     for (let i = 0; i < spots.length; i++) {
325:       const sp = spots[i];
326:       if (i < 30) {
327:         const id = weaponIds[wi % weaponIds.length];
328:         wi++;
329:         this.spawnLootAt(sp.x, sp.z, 'weapon', id, 0);
330:       } else if (i < 54) {
331:         this.spawnLootAt(sp.x, sp.z, 'ammo', null, 0);
332:       } else if (i < 74) {
333:         this.spawnLootAt(sp.x, sp.z, 'medkit', null, 0);
334:       }
335:     }
336:   }
