338:   spawnLootAt(x, z, type, weaponId = null, delay = 0) {
339:     if (!this.matchGroup) return null;
340:     let mesh;
341:     if (type === 'weapon' && weaponId) mesh = makeLootWeapon(weaponId);
342:     else if (type === 'ammo') mesh = makeAmmoBox();
343:     else mesh = makeMedkit();
344:     const y = this.world.groundHeight(x, z, Infinity) + 0.22;
345:     mesh.position.set(x, y, z);
346:     mesh.rotation.y = Math.random() * Math.PI * 2;
347:     mesh.visible = delay <= 0;
348:     this.matchGroup.add(mesh);
349:     const item = {
350:       type, weaponId, x, z, baseY: y, mesh,
351:       ring: mesh.userData.ring || null,
352:       taken: false, delay, phase: Math.random() * 6
353:     };
354:     this.loot.push(item);
355:     return item;
356:   }
