358:   _updateLoot(dt) {
359:     let nearest = null, nearestD = 3.8;
360:     const px = this.player.p.pos.x, pz = this.player.p.pos.z;
361:     for (const item of this.loot) {
362:       if (item.taken) continue;
363:       if (item.delay > 0) {
364:         item.delay -= dt;
365:         if (item.delay <= 0) item.mesh.visible = true;
366:         continue;
367:       }
368:       item.mesh.position.y = item.baseY + Math.sin(this.time * 2 + item.phase) * 0.055;
369:       if (item.ring) item.ring.rotation.z += dt * 1.15;
370:       const d = Math.hypot(item.x - px, item.z - pz);
371:       if (d < nearestD) { nearestD = d; nearest = item; }
372:     }
373:     this.nearLoot = nearest;
374:     if (!this.player.p.alive || this.player.p.dropping) {
375:       this.ui.setPickup(null);
376:       return;
377:     }
378:     if (!nearest) { this.ui.setPickup(null); return; }
379:     this.ui.setPickup(this._pickupPrompt(nearest));
380:   }
381: 
382:   _pickupPrompt(item) {
383:     if (item.type === 'weapon') {
384:       const def = WEAPONS[item.weaponId];
385:       const owned = this.player.p.slots.some((s) => s && s.id === item.weaponId);
386:       const empty = this.player.p.slots.some((s) => !s);
387:       if (owned) return { action: 'AMMO', name: def.name, sub: '+ RESERVE AMMO' };
388:       return { action: empty ? 'PICK UP' : 'SWAP', name: def.name, sub: def.category };
389:     }
390:     if (item.type === 'ammo') return { action: 'PICK UP', name: 'AMMO BOX', sub: '+ RESERVE' };
391:     return { action: 'PICK UP', name: 'MEDKIT', sub: '+1 MEDKIT' };
392:   }
