399:   _pickupItem(item) {
400:     if (!item || item.taken || item.delay > 0) return;
401:     if (item.type === 'weapon') {
402:       const def = WEAPONS[item.weaponId];
403:       const res = this.player.giveWeapon(item.weaponId);
404:       if (res.oldId) {
405:         this.spawnLootAt(this.player.p.pos.x + rand(-1.4, 1.4), this.player.p.pos.z + rand(-1.4, 1.4), 'weapon', res.oldId, 1.5);
406:       }
407:       this.ui.showBanner('LOOT', `${def.name} ${res.type === 'ammo' ? 'AMMO' : 'ACQUIRED'}`, 900);
408:       this.audio.pickup();
409:     } else if (item.type === 'ammo') {
410:       this.player.giveAmmo(30);
411:       this.ui.showBanner('LOOT', '+30 RESERVE AMMO', 850);
412:       this.audio.pickup();
413:     } else if (item.type === 'medkit') {
414:       if (this.player.p.medkits >= 5) {
415:         this.ui.showBanner('MEDKIT', 'MEDKIT POUCH FULL', 900);
416:         return;
417:       }
418:       this.player.giveMedkit();
419:       this.ui.showBanner('LOOT', '+1 MEDKIT', 850);
420:       this.audio.pickup();
421:     }
422:     item.taken = true;
423:     item.mesh.visible = false;
424:     if (this.nearLoot === item) this.nearLoot = null;
425:     this.ui.setPickup(null);
426:   }
