428:   _updateMatch(dt) {
429:     this.matchTime += dt;
430:     const p = this.player.p;
431:     const forward = (this.keys.KeyW ? 1 : 0) - (this.keys.KeyS ? 1 : 0) - this.touchMove.y;
432:     const right = (this.keys.KeyD ? 1 : 0) - (this.keys.KeyA ? 1 : 0) + this.touchMove.x;
433:     const input = {
434:       forward, right,
435:       jump: this.jumpQueued,
436:       sprint: !!(this.keys.ShiftLeft || this.keys.ShiftRight) || Math.hypot(this.touchMove.x, this.touchMove.y) > 0.92,
437:       crouch: this.crouchToggle
438:     };
439:     this.jumpQueued = false;
440:     this.player.update(dt, input, this.time);
441:     this.botManager.update(dt);
442:     this._updateZone(dt);
443:     this._updateLoot(dt);
444:     this._updateHud(dt);
445:     this._followShadow();
446:     this.checkVictory();
447:     if (p.alive) {
448:       const z = this.zone;
449:       const outside = Math.hypot(p.pos.x - z.x, p.pos.z - z.z) > z.radius;
450:       if (outside) {
451:         p.zoneTick += dt;
452:         if (p.zoneTick >= 0.5) {
453:           p.zoneTick = 0;
454:           this.player.takeDamage(z.damage * 0.5, null, 'ZONE');
455:         }
456:       } else p.zoneTick = 0;
457:     }
458:   }
459: 
460:   _updateZone(dt) {
461:     const z = this.zone;
462:     if (!z) return;
463:     if (z.state === 'wait') {
464:       z.timer -= dt;
465:       if (z.timer <= 0) {
466:         z.state = 'shrink';
467:         z.shrinkDuration = Math.max(10, 22 - z.phase * 1.5);
468:         z.timer = z.shrinkDuration;
469:         z.startX = z.x; z.startZ = z.z; z.startRadius = z.radius;
470:         z.targetX = z.nextX; z.targetZ = z.nextZ; z.targetRadius = z.nextRadius;
471:         this.ui.showBanner('STORM', 'SAFE ZONE SHRINKING', 1600);
472:         this.audio.zone();
473:       }
474:     } else if (z.state === 'shrink') {
475:       z.timer -= dt;
476:       const t = 1 - clamp(z.timer / z.shrinkDuration, 0, 1);
477:       z.x = lerp(z.startX, z.targetX, t);
478:       z.z = lerp(z.startZ, z.targetZ, t);
479:       z.radius = lerp(z.startRadius, z.targetRadius, t);
480:       if (z.timer <= 0) {
481:         z.x = z.targetX; z.z = z.targetZ; z.radius = z.targetRadius;
482:         z.phase += 1;
483:         z.state = 'wait';
484:         z.timer = Math.max(11, 24 - z.phase * 1.5);
485:         z.damage = 1.5 + z.phase * 1.4;
486:         this._computeNextZone(z);
487:         this.audio.zone();
488:       }
489:     }
490:     if (this.zoneMesh) {
491:       this.zoneMesh.position.set(z.x, 70, z.z);
492:       this.zoneMesh.scale.set(z.radius, 1, z.radius);
493:       const pulse = 0.12 + Math.sin(this.time * 2.4) * 0.035;
494:       this.zoneMesh.material.opacity = pulse;
495:       const outside = Math.hypot(this.player.p.pos.x - z.x, this.player.p.pos.z - z.z) > z.radius;
496:       this.zoneMesh.material.color.setHex(outside ? 0xb03cff : 0x8a3cff);
497:     }
498:   }
