428:     if (!this.world || !this.minimapCtx) return;
429:     const ctx = this.minimapCtx;
430:     const S = 240;
431:     ctx.clearRect(0, 0, S, S);
432:     ctx.drawImage(this.world.minimapCanvas, 0, 0, S, S);
433:     const toPx = (x, z) => [((x + 500) / 1000) * S, ((z + 500) / 1000) * S];
434: 
435:     // Storm overlay
436:     const [zx, zy] = toPx(state.zone.x, state.zone.z);
437:     const zr = (state.zone.radius / 1000) * S;
438:     ctx.save();
439:     ctx.beginPath();
440:     ctx.rect(0, 0, S, S);
441:     ctx.arc(zx, zy, zr, 0, Math.PI * 2, true);
442:     ctx.fillStyle = 'rgba(126, 37, 177, .38)';
443:     ctx.fill('evenodd');
444:     ctx.restore();
445:     ctx.beginPath();
446:     ctx.arc(zx, zy, zr, 0, Math.PI * 2);
447:     ctx.strokeStyle = 'rgba(190, 120, 255, .95)';
448:     ctx.lineWidth = 1.6;
449:     ctx.stroke();
450: 
451:     if (state.zone.nextRadius && state.zone.nextRadius > 0) {
452:       const [nx, ny] = toPx(state.zone.nextX, state.zone.nextZ);
453:       ctx.beginPath();
454:       ctx.setLineDash([3, 4]);
455:       ctx.arc(nx, ny, (state.zone.nextRadius / 1000) * S, 0, Math.PI * 2);
456:       ctx.strokeStyle = 'rgba(255,255,255,.5)';
457:       ctx.lineWidth = 1;
458:       ctx.stroke();
459:       ctx.setLineDash([]);
460:     }
461: 
462:     // POIs
463:     for (const p of state.pois) {
464:       const [px, py] = toPx(p.x, p.z);
465:       ctx.fillStyle = p.color;
466:       ctx.beginPath();
467:       ctx.arc(px, py, 2.4, 0, Math.PI * 2);
468:       ctx.fill();
469:       ctx.font = '700 7px Rajdhani, Arial, sans-serif';
470:       ctx.fillStyle = 'rgba(255,255,255,.72)';
471:       ctx.textAlign = 'center';
472:       ctx.fillText(p.short, px, py - 5);
473:     }
474: 
475:     // Nearby loot
476:     for (const l of state.nearLoot || []) {
477:       const [lx, ly] = toPx(l.x, l.z);
478:       ctx.fillStyle = 'rgba(255,210,63,.9)';
479:       ctx.fillRect(lx - 1, ly - 1, 2, 2);
