481: 
482:     // Nearby enemies
483:     for (const b of state.nearBots || []) {
484:       const [bx, by] = toPx(b.x, b.z);
485:       ctx.beginPath();
486:       ctx.arc(bx, by, 2.3, 0, Math.PI * 2);
487:       ctx.fillStyle = b.visible ? '#ff4a3d' : 'rgba(255,74,61,.45)';
488:       ctx.fill();
489:     }
490: 
491:     // Player arrow
492:     const [px, py] = toPx(state.player.x, state.player.z);
493:     ctx.save();
494:     ctx.translate(px, py);
495:     ctx.rotate(-state.player.yaw);
496:     ctx.beginPath();
497:     ctx.moveTo(0, -6.5);
498:     ctx.lineTo(4.4, 5);
499:     ctx.lineTo(0, 2.6);
500:     ctx.lineTo(-4.4, 5);
501:     ctx.closePath();
502:     ctx.fillStyle = '#ffffff';
503:     ctx.strokeStyle = 'rgba(0,0,0,.8)';
504:     ctx.lineWidth = 1.2;
505:     ctx.fill();
506:     ctx.stroke();
507:     ctx.restore();
