          <button id="mod-done" class="primary-btn" type="button">BACK TO MATCH</button>
        </div>
        <div class="mod-warning">USE RESPONSIBLY — AIMKILL / AIMLOCK ARE FOR OFFLINE SANDBOX PLAY.</div>
      </div>
    </div>
  </div>
